    fn temp_profile_registry_path(label: &str) -> String {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        std::env::temp_dir()
            .join(format!(
                "trnm-tee-profile-registry-{}-{}-{}.json",
                label,
                std::process::id(),
                unique
            ))
            .display()
            .to_string()
    }

